                alert(`Thank you for subscribing with ${email}! Check your inbox for a welcome offer.`);
                input.value = '';
                input.focus();
            } else {
                alert('Please enter a valid email address.');
            }
        }

        // Add to cart feedback
        document.querySelectorAll('.product-btn').forEach(btn => {
